/**
 * ADR-058: Generate domain event types and event bus infrastructure.
 * Each bounded context's domain events become typed interfaces.
 */
function tsDomainEvents(contexts: DDDContext[]): string {
  const lines: string[] = [
    GENERATED_HEADER_TS,
    "import { randomUUID } from 'node:crypto';",
    '',
    '// ============================================================================',
    '// Domain Event Infrastructure (ADR-058)',
    '// ============================================================================',
    '',
    '/** Base domain event — all events extend this interface. */',
    'export interface DomainEvent<T = unknown> {',
    '  readonly eventId: string;',
    '  readonly eventType: string;',
    '  readonly aggregateId: string;',
    '  readonly aggregateType: string;',
    '  readonly payload: T;',
    '  readonly timestamp: string;',
    '  readonly correlationId: string;',
    '  readonly causationId: string;',
    '}',
    '',
  ];

  // Generate typed events from each context's domainEvents
  const allEventTypes: string[] = [];
  for (const ctx of contexts) {
    if (ctx.domainEvents.length === 0) continue;
    const ctxPascal = pascalCase(ctx.name);
    lines.push(`// Events from ${ctxPascal}`);

    for (const evt of ctx.domainEvents) {
      const eventName = pascalCase(evt.name);
      allEventTypes.push(eventName);
      const payloadFields = (evt.payload ?? []).filter(Boolean);

      lines.push(`export interface ${eventName}Event extends DomainEvent<{`);
      if (payloadFields.length > 0) {
        for (const field of payloadFields) {
          const fieldName = field.replace(/[^a-zA-Z0-9_]/g, '_');
          lines.push(`  ${fieldName}: unknown;`);
        }
      } else {
        lines.push('  [key: string]: unknown;');
      }
      lines.push('}> {');
      lines.push(`  readonly eventType: '${evt.name}';`);
      lines.push('}');
      lines.push('');
    }
  }

  // Event type union
  if (allEventTypes.length > 0) {
    lines.push(`export type AllDomainEvents = ${allEventTypes.map(e => `${e}Event`).join(' | ')};`);
  } else {
    lines.push('export type AllDomainEvents = DomainEvent;');
  }
  lines.push('');

  // Event bus interface + console implementation
  lines.push('// ============================================================================');
  lines.push('// Event Bus');
  lines.push('// ============================================================================');
  lines.push('');
  lines.push('export interface IEventBus {');
  lines.push('  publish(event: DomainEvent): Promise<void>;');
  lines.push('  subscribe(eventType: string, handler: (event: DomainEvent) => Promise<void>): void;');
  lines.push('}');
  lines.push('');
  lines.push('/** Console-based event bus — logs events as structured JSON. */');
  lines.push('/** Replace with Kafka/PubSub/EventBridge in production. */');
  lines.push('export class ConsoleEventBus implements IEventBus {');
  lines.push('  private handlers = new Map<string, Array<(event: DomainEvent) => Promise<void>>>();');
  lines.push('');
  lines.push('  async publish(event: DomainEvent): Promise<void> {');
  lines.push("    console.log(JSON.stringify({ type: 'DOMAIN_EVENT', ...event }));");
  lines.push('    const fns = this.handlers.get(event.eventType) ?? [];');
  lines.push('    for (const fn of fns) { await fn(event); }');
  lines.push('  }');
  lines.push('');
  lines.push('  subscribe(eventType: string, handler: (event: DomainEvent) => Promise<void>): void {');
  lines.push('    const existing = this.handlers.get(eventType) ?? [];');
  lines.push('    existing.push(handler);');
  lines.push('    this.handlers.set(eventType, existing);');
  lines.push('  }');
  lines.push('}');
  lines.push('');
  lines.push('/** ADR-077: Observatory-backed event bus — sends events to the platform for pattern analysis. */');
  lines.push('export class ObservatoryEventBus extends ConsoleEventBus {');
  lines.push('  private readonly observatoryUrl: string;');
  lines.push('');
  lines.push('  constructor(observatoryUrl: string) {');
  lines.push('    super();');
  lines.push('    this.observatoryUrl = observatoryUrl;');
  lines.push('  }');
  lines.push('');
  lines.push('  override async publish(event: DomainEvent): Promise<void> {');
  lines.push('    // Local handlers + console logging first');
  lines.push('    await super.publish(event);');
  lines.push('    // Fire-and-forget to Observatory for pattern analysis');
  lines.push('    fetch(`${this.observatoryUrl}/api/v1/telemetry/events`, {');
  lines.push('      method: \'POST\',');
  lines.push('      headers: { \'Content-Type\': \'application/json\' },');
  lines.push('      body: JSON.stringify({');
  lines.push('        type: event.eventType,');
  lines.push('        aggregateType: event.aggregateType,');
  lines.push('        aggregateId: event.aggregateId,');
  lines.push('        payload: event.payload,');
  lines.push('        timestamp: event.timestamp,');
  lines.push('        correlationId: event.correlationId,');
  lines.push('      }),');
  lines.push('      signal: AbortSignal.timeout(5_000),');
  lines.push("    }).catch(() => { /* operational tier — Observatory unavailable */ });");
  lines.push('  }');
  lines.push('}');
  lines.push('');
  lines.push('/** Create a domain event with auto-generated ID and timestamp. */');
  lines.push('export function createEvent<T>(');
  lines.push('  eventType: string,');
  lines.push('  aggregateType: string,');
  lines.push('  aggregateId: string,');
  lines.push('  payload: T,');
  lines.push('  correlationId: string,');
  lines.push('  causationId: string,');
  lines.push('): DomainEvent<T> {');
  lines.push('  return {');
  lines.push('    eventId: randomUUID(),');
  lines.push('    eventType,');
  lines.push('    aggregateType,');
  lines.push('    aggregateId,');
  lines.push('    payload,');
  lines.push('    timestamp: new Date().toISOString(),');
  lines.push('    correlationId,');
  lines.push('    causationId,');
  lines.push('  };');
  lines.push('}');
  lines.push('');

  return lines.join('\n');
}

/**
 * ADR-PIPELINE-064: Server-wide typed Hono context variables.
 *
 * Emits `src/server/types.ts` exporting the `ContextVariables` interface,
 * `IamClaims` interface, and the `AppEnv` type alias. These are consumed
 * by routes.ts (`new Hono<AppEnv>()`), middleware.ts (`createMiddleware<AppEnv>()`),
 * and health.ts — eliminating `c.get('correlationId') as string` casts and
 * `Record<string, unknown>` on iamClaims.
 */
// Exported for unit tests (ADR-PIPELINE-064 verification)
export function tsServerTypes(): string {
  return [
    GENERATED_HEADER_TS,
    '// ADR-PIPELINE-064: Typed Hono context variables eliminate unsafe type assertions.',
    '// Every middleware that calls c.set() MUST add its key to ContextVariables.',
    '// Route handlers use getCorrelationId(c), getActor(c), getActorRoles(c) helpers',
    '// (declared in routes.ts) rather than reading context directly.',
    '',
    '/** Claims extracted from a verified IAM JWT token. */',
    'export interface IamClaims {',
    '  sub?: string;',
    '  roles?: string[];',
    '  iss?: string;',
    '  aud?: string | string[];',
    '  exp?: number;',
    '  iat?: number;',
    '  [claim: string]: unknown;',
    '}',
    '',
    '/** Hono context variables set by middleware and read by route handlers. */',
    'export interface ContextVariables {',
    '  correlationId: string;',
    '  iamClaims?: IamClaims;',
    '}',
    '',
    '/** Hono environment type — use as `new Hono<AppEnv>()` and `createMiddleware<AppEnv>()`. */',
    'export type AppEnv = { Variables: ContextVariables };',
    '',
  ].join('\n');
}

// Exported for unit tests (ADR-PIPELINE-064 verification)
export function tsMiddleware(): string {
  return [
    GENERATED_HEADER_TS,
    `import type { MiddlewareHandler } from 'hono';`,
    `import { createMiddleware } from 'hono/factory';`,
    `import type { AppEnv, IamClaims } from './types.js';`,
    `import * as crypto from 'node:crypto';`,
    `import * as jwt from 'jsonwebtoken';`,
    `import jwksClient from 'jwks-rsa';`,
    '',
    '// ---------------------------------------------------------------------------',
    '// Correlation ID middleware',
    '// ---------------------------------------------------------------------------',
    '',
    'export const correlationMiddleware: MiddlewareHandler = createMiddleware<AppEnv>(async (c, next) => {',
    '  const correlationId = c.req.header(\'X-Correlation-ID\') ?? crypto.randomUUID();',
    '  c.set(\'correlationId\', correlationId);',
    '  c.header(\'X-Correlation-ID\', correlationId);',
    '  await next();',
    '});',
    '',
    '// ---------------------------------------------------------------------------',
    '// IAM token validation middleware (JWKS-backed JWT verification)',
    '// ---------------------------------------------------------------------------',
    '',
    'const JWKS_URI = process.env.IAM_JWKS_URI ?? \'https://www.googleapis.com/oauth2/v3/certs\';',
    'const IAM_AUDIENCE = process.env.IAM_AUDIENCE ?? \'\';',
    'const IAM_ISSUERS = (process.env.IAM_ISSUERS ?? \'https://accounts.google.com\').split(\',\').map(s => s.trim());',
    '',
    'const jwksRsa = jwksClient({',
    '  jwksUri: JWKS_URI,',
    '  cache: true,',
    '  cacheMaxAge: 600_000,',
    '  rateLimit: true,',
    '  jwksRequestsPerMinute: 10,',
    '});',
    '',
    'function getSigningKey(kid: string): Promise<string> {',
    '  return new Promise((resolve, reject) => {',
    '    jwksRsa.getSigningKey(kid, (err, key) => {',
    '      if (err || !key) return reject(err ?? new Error(\'No signing key found\'));',
    '      resolve(key.getPublicKey());',
    '    });',
    '  });',
    '}',
    '',
    'export const iamMiddleware: MiddlewareHandler = createMiddleware<AppEnv>(async (c, next) => {',
    '  const path = new URL(c.req.url).pathname;',
    '  if (path === \'/health/healthz\' || path === \'/health/readyz\' || path === \'/metrics\') {',
    '    await next();',
    '    return;',
    '  }',
    '',
    '  // ADR-051: Auth errors include correlationId for traceability',
    '  const correlationId = getCorrelationId(c);',
    '  const authHeader = c.req.header(\'Authorization\');',
    '  if (!authHeader?.startsWith(\'Bearer \')) {',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Missing Bearer token\' }, correlationId }, 401);',
    '  }',
    '',
    '  const token = authHeader.slice(7);',
    '  if (!token) {',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Empty token\' }, correlationId }, 401);',
    '  }',
    '',
    '  try {',
    '    const decoded = jwt.decode(token, { complete: true });',
    '    if (!decoded || typeof decoded === \'string\' || !decoded.header.kid) {',
    '      return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Malformed token: missing kid\' } }, 401);',
    '    }',
    '',
    '    const signingKey = await getSigningKey(decoded.header.kid);',
    '',
    '    const verifyOptions: jwt.VerifyOptions = {',
    '      algorithms: [\'RS256\', \'RS384\', \'RS512\', \'ES256\', \'ES384\'],',
    '    };',
    '    if (IAM_ISSUERS.length > 0 && IAM_ISSUERS[0] !== \'\') {',
    '      verifyOptions.issuer = IAM_ISSUERS;',
    '    }',
    '    if (IAM_AUDIENCE) {',
    '      verifyOptions.audience = IAM_AUDIENCE;',
    '    }',
    '',
    '    const payload = jwt.verify(token, signingKey, verifyOptions);',
    '    if (typeof payload === \'string\') {',
    '      return c.json({ error: { code: \'UNAUTHORIZED\', message: \'Invalid token: string payload\' }, correlationId }, 401);',
    '    }',
    '    // ADR-PIPELINE-064: typed context variables — payload is narrowed to an object here',
    '    c.set(\'iamClaims\', payload as IamClaims);',
    '  } catch (err) {',
    '    const message = err instanceof Error ? err.message : \'Token verification failed\';',
    '    console.warn(JSON.stringify({ level: \'warn\', type: \'AUTH_FAILURE\', correlationId, error: message, path: c.req.path }));',
    '    return c.json({ error: { code: \'UNAUTHORIZED\', message }, correlationId }, 401);',
    '  }',
    '',
    '  await next();',
    '});',
    '',
    '// ---------------------------------------------------------------------------',
    '// Structured JSON request/response logging middleware',
    '// ---------------------------------------------------------------------------',
    '',
    'export const loggingMiddleware: MiddlewareHandler = createMiddleware<AppEnv>(async (c, next) => {',
    '  const startTime = Date.now();',
    '  const correlationId = c.get(\'correlationId\');',
    '',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'request received\',',
    '      httpRequest: {',
    '        method: c.req.method,',
    '        url: c.req.url,',
    '        userAgent: c.req.header(\'user-agent\'),',
    '      },',
    '      correlationId,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '',
    '  await next();',
    '',
    '  const durationMs = Date.now() - startTime;',
    '  process.stdout.write(',
    '    JSON.stringify({',
    '      severity: \'INFO\',',
    '      message: \'request completed\',',
    '      httpRequest: {',
    '        method: c.req.method,',
    '        url: c.req.url,',
    '        status: c.res.status,',
    '        latency: `${durationMs}ms`,',
    '      },',
    '      correlationId,',
    '      timestamp: new Date().toISOString(),',
    '    }) + \'\\n\',',
    '  );',
    '});',
    '',
  ].join('\n');
}

// Exported for unit tests (ADR-PIPELINE-064 verification)
export function tsHealth(): string {
  return [
    GENERATED_HEADER_TS,
    `import { Hono } from 'hono';`,
    `import type { AppEnv } from './types.js';`,
    '',
    '// ADR-050: Real health checks that verify downstream dependencies',
    '// ADR-PIPELINE-064: healthRouter is typed with AppEnv so it can be mounted',
    '// on the main app (also typed with AppEnv) without variance errors.',
    'export function createHealthRouter(deps: {',
    '  db?: { query(sql: string, params: unknown[]): Promise<unknown[]> };',
    '  erp?: { getSyncStatus(): { circuit_breaker_state: string } };',
    '}): Hono<AppEnv> {',
    '  const healthRouter = new Hono<AppEnv>();',
    '',
    '  // Liveness — is the process running?',
    '  healthRouter.get(\'/healthz\', (c) => {',
    '    return c.json({ status: \'ok\' }, 200);',
    '  });',
    '',
    '  // Readiness — can the service handle requests?',
    '  healthRouter.get(\'/readyz\', async (c) => {',
    '    const checks: Record<string, \'ok\' | \'fail\'> = {};',
    '',
    '    // ADR-059: Database connectivity check — reports not_configured when no DATABASE_URL',
    '    if (!process.env.DATABASE_URL) {',
    '      checks.database = \'fail\';  // No DB configured — system is NOT ready',
    '    } else if (deps.db) {',
    '      try {',
    '        await deps.db.query(\'SELECT 1\', []);',
    '        checks.database = \'ok\';',
    '      } catch (err) {',
    '        console.error(JSON.stringify({ level: \'error\', check: \'database\', error: err instanceof Error ? err.message : String(err) }));',
    '        checks.database = \'fail\';',
    '      }',
    '    }',
    '',
    '    // ERP circuit breaker check',
    '    if (deps.erp) {',
    '      try {',
    '        const status = deps.erp.getSyncStatus();',
    '        checks.erp = status.circuit_breaker_state === \'open\' ? \'fail\' : \'ok\';',
    '      } catch {',
    '        checks.erp = \'fail\';',
    '      }',
    '    }',
    '',
    '    const allOk = Object.values(checks).every(v => v === \'ok\');',
    '    return c.json({',
    '      status: allOk ? \'ready\' : \'degraded\',',
    '      checks,',
    '    }, allOk ? 200 : 503);',
    '  });',
    '',
    '  return healthRouter;',
    '}',
    '',
    '// Backwards-compatible default export for simple usage',
    'export const healthRouter = createHealthRouter({});',
    '',
  ].join('\n');
}

