function tsHealthTest(): string {
  return [
    GENERATED_HEADER_TS,
    `import { describe, it, expect } from 'vitest';`,
    `import { Hono } from 'hono';`,
    `import { createHealthRouter, healthRouter } from '../server/health.js';`,
    '',
    'describe(\'Health Endpoints\', () => {',
    '  it(\'GET /health/healthz returns 200 (liveness)\', async () => {',
    '    const app = new Hono().route(\'/health\', healthRouter);',
    '    const res = await app.request(\'/health/healthz\');',
    '    expect(res.status).toBe(200);',
    '    const body = await res.json();',
    '    expect(body.status).toBe(\'ok\');',
    '  });',
    '',
    '  it(\'GET /health/readyz returns 200 when deps healthy and DATABASE_URL set\', async () => {',
    '    const origDbUrl = process.env.DATABASE_URL;',
    "    process.env.DATABASE_URL = 'postgresql://test:test@localhost/test';",
    '    try {',
    '      const router = createHealthRouter({',
    '        db: { query: async () => [{ result: 1 }] },',
    '        erp: { getSyncStatus: () => ({ circuit_breaker_state: \'closed\' }) },',
    '      });',
    '      const app = new Hono().route(\'/health\', router);',
    '      const res = await app.request(\'/health/readyz\');',
    '      expect(res.status).toBe(200);',
    '      const body = await res.json();',
    '      expect(body.status).toBe(\'ready\');',
    '      expect(body.checks.database).toBe(\'ok\');',
    '      expect(body.checks.erp).toBe(\'ok\');',
    '    } finally {',
    '      if (origDbUrl) process.env.DATABASE_URL = origDbUrl;',
    '      else delete process.env.DATABASE_URL;',
    '    }',
    '  });',
    '',
    '  it(\'GET /health/readyz returns 503 when DATABASE_URL not set (ADR-059)\', async () => {',
    '    const origDbUrl = process.env.DATABASE_URL;',
    '    delete process.env.DATABASE_URL;',
    '    try {',
    '      const router = createHealthRouter({});',
    '      const app = new Hono().route(\'/health\', router);',
    '      const res = await app.request(\'/health/readyz\');',
    '      expect(res.status).toBe(503);',
    '      const body = await res.json();',
    '      expect(body.checks.database).toBe(\'fail\');',
    '    } finally {',
    '      if (origDbUrl) process.env.DATABASE_URL = origDbUrl;',
    '    }',
    '  });',
    '',
    '  it(\'GET /health/readyz returns 503 when db down\', async () => {',
    '    const router = createHealthRouter({',
    '      db: { query: async () => { throw new Error(\'connection refused\'); } },',
    '    });',
    '    const app = new Hono().route(\'/health\', router);',
    '    const res = await app.request(\'/health/readyz\');',
    '    expect(res.status).toBe(503);',
    '    const body = await res.json();',
    '    expect(body.status).toBe(\'degraded\');',
    '    expect(body.checks.database).toBe(\'fail\');',
    '  });',
    '',
    '  it(\'GET /health/readyz returns 503 when circuit breaker open\', async () => {',
    '    const router = createHealthRouter({',
    '      erp: { getSyncStatus: () => ({ circuit_breaker_state: \'open\' }) },',
    '    });',
    '    const app = new Hono().route(\'/health\', router);',
    '    const res = await app.request(\'/health/readyz\');',
    '    expect(res.status).toBe(503);',
    '    const body = await res.json();',
    '    expect(body.checks.erp).toBe(\'fail\');',
    '  });',
    '});',
    '',
  ].join('\n');
}

function tsContextTest(ctx: DDDContext): string {
  const ctxPascal = pascalCase(ctx.name);
  const ctxSnake = snakeCase(ctx.name);
  const ctxLabel = ctx.name.replace(/-/g, ' ');
  const tableName = `${ctxSnake}_records`;

  // ADR-060: Unit tests import real adapters via createDependencies + in-memory DB
  const lines: string[] = [
    GENERATED_HEADER_TS,
    `import { describe, it, expect, beforeAll, afterAll } from 'vitest';`,
    `import { randomUUID } from 'node:crypto';`,
    `import { createDependencies } from '../server/dependencies.js';`,
    `import type { ${ctxPascal}Record } from '../server/dependencies.js';`,
    '',
    `// ADR-060: In-memory DbClient that executes real SQL via Map store`,
    '// This tests the REAL adapter (not a mock) with a simple backing store',
    'function createInMemoryDb() {',
    '  const tables: Record<string, Record<string, unknown>[]> = {};',
    '',
    '  return {',
    '    async query(sql: string, params: unknown[]): Promise<unknown[]> {',
    `      const table = '${tableName}';`,
    '      if (!tables[table]) tables[table] = [];',
    '      // Handle COUNT',
    "      if (sql.includes('COUNT(*)')) return [{ cnt: tables[table].length }];",
    '      // Handle SELECT by id',
    "      if (sql.includes('WHERE id')) {",
    '        return tables[table].filter(r => r.id === params[0]);',
    '      }',
    '      // Handle SELECT with LIMIT/OFFSET',
    '      const limit = typeof params[params.length - 2] === \'number\' ? params[params.length - 2] as number : 50;',
    '      const offset = typeof params[params.length - 1] === \'number\' ? params[params.length - 1] as number : 0;',
    '      return tables[table].slice(offset, offset + limit);',
    '    },',
    '    async execute(sql: string, params: unknown[]): Promise<void> {',
    `      const table = '${tableName}';`,
    '      if (!tables[table]) tables[table] = [];',
    "      if (sql.includes('INSERT')) {",
    '        tables[table].push({ id: params[0], status: params[1], created_at: params[2], updated_at: params[3], data: params[4] });',
    '      }',
    "      if (sql.includes('audit_log')) {",
    "        if (!tables['audit_log']) tables['audit_log'] = [];",
    "        tables['audit_log'].push({ id: params[0] });",
    '      }',
    '    },',
    '  };',
    '}',
    '',
    `describe('${ctxLabel} Port (real adapter)', () => {`,
    '  let adapter: any;',
    '',
    '  beforeAll(() => {',
    '    const db = createInMemoryDb();',
    '    const erp = { async invoke() { return {}; } };',
    '    const deps = createDependencies(db as any, erp as any);',
    `    adapter = deps.${camelCase(ctx.name)};`,
    '  });',
    '',
    `  it('execute() creates a record via real adapter', async () => {`,
    `    const result = await adapter.execute('TestCreate', { name: 'test-entity' });`,
    `    expect(result.id).toBeDefined();`,
    `    expect(typeof result.id).toBe('string');`,
    `    expect(result.id.length).toBeGreaterThan(0);`,
    `    expect(result.status).toBe('TestCreate');`,  // ADR-048: status = command name
    `    expect(result.created_at).toBeDefined();`,
    '  });',
    '',
    `  it('getById() retrieves a created record', async () => {`,
    `    const created = await adapter.execute('TestGetById', { value: 42 });`,
    '    const found = await adapter.getById(created.id);',
    '    expect(found).not.toBeNull();',
    '    expect(found.id).toBe(created.id);',
    '  });',
    '',
    `  it('getById() returns null for non-existent id', async () => {`,
    "    const found = await adapter.getById('non-existent-' + randomUUID().slice(0, 8));",
    '    expect(found).toBeNull();',
    '  });',
    '',
    `  it('query() returns paginated results', async () => {`,
    `    await adapter.execute('Insert1', { idx: 1 });`,
    `    await adapter.execute('Insert2', { idx: 2 });`,
    `    await adapter.execute('Insert3', { idx: 3 });`,
    '    const result = await adapter.query({}, 2, 0);',
    '    expect(result.rows.length).toBeLessThanOrEqual(2);',
    '    expect(result.total).toBeGreaterThanOrEqual(3);',
    '  });',
    '});',
    '',
  ];

  return lines.join('\n');
}

/**
 * ADR-055: Generate integration test that tests real adapter against SQLite.
 * Tests actual SQL execution, not mock behavior.
 */
function tsContextIntegrationTest(ctx: DDDContext): string {
  const ctxSnake = snakeCase(ctx.name);
  const ctxLabel = ctx.name.replace(/-/g, ' ');
  const tableName = `${ctxSnake}_records`;

  return [
    GENERATED_HEADER_TS,
    `import { describe, it, expect, beforeEach, afterEach } from 'vitest'; // ADR-087: per-test isolation`,
    `import Database from 'better-sqlite3';`,
    `import { ConsoleTelemetry } from '../infra/telemetry.js';`,
    '',
    `// Integration test: ${ctxLabel} adapter against real SQLite database`,
    `// Tests actual SQL execution, parameterized queries, and filter logic`,
    '',
    `// Minimal DbClient wrapper around better-sqlite3`,
    'function createTestDb() {',
    "  const db = new Database(':memory:');",
    `  db.exec(\`CREATE TABLE ${tableName} (`,
    '    id TEXT PRIMARY KEY,',
    '    status TEXT NOT NULL,',
    '    created_at TEXT NOT NULL,',
    '    updated_at TEXT NOT NULL,',
    '    data TEXT NOT NULL',
    '  )\`);',
    `  db.exec(\`CREATE TABLE audit_log (`,
    '    id TEXT PRIMARY KEY,',
    '    entity_type TEXT NOT NULL,',
    '    entity_id TEXT NOT NULL,',
    '    action TEXT NOT NULL,',
    '    actor TEXT NOT NULL,',
    '    payload TEXT,',
    '    previous_hash TEXT,',
    '    actor_role TEXT,',
    '    source_ip TEXT,',
    '    request_id TEXT,',
    '    created_at TEXT NOT NULL',
    '  )\`);',
    '  // ADR-083: simulation_runs table for lineage validation',
    `  db.exec(\`CREATE TABLE IF NOT EXISTS simulation_runs (`,
    '    id TEXT PRIMARY KEY,',
    '    input_hash TEXT NOT NULL,',
    '    parameters TEXT NOT NULL,',
    '    status TEXT NOT NULL DEFAULT \'completed\',',
    '    result_summary TEXT,',
    '    created_at TEXT NOT NULL',
    '  )\`);',
    '  // ADR-083: decisions table for lineage validation',
    `  db.exec(\`CREATE TABLE IF NOT EXISTS decisions (`,
    '    id TEXT PRIMARY KEY,',
    '    simulation_run_id TEXT NOT NULL,',
    '    strategy_id TEXT NOT NULL,',
    '    recommended_action TEXT NOT NULL,',
    '    justification TEXT NOT NULL,',
    '    status TEXT NOT NULL DEFAULT \'submitted\',',
    '    submitted_by TEXT NOT NULL,',
    '    approved_by TEXT,',
    '    rejected_by TEXT,',
    '    rejection_reason TEXT,',
    '    executed_by TEXT,',
    '    created_at TEXT NOT NULL,',
    '    updated_at TEXT NOT NULL',
    '  )\`);',
    '  return {',
    '    db,',
    '    client: {',
    '      async query(sql: string, params: unknown[]): Promise<unknown[]> {',
    '        // Convert :N placeholders to ? for SQLite',
    '        let idx = 0;',
    "        const sqliteSql = sql.replace(/:[0-9]+/g, () => { idx++; return '?'; });",
    '        return db.prepare(sqliteSql).all(...params);',
    '      },',
    '      async execute(sql: string, params: unknown[]): Promise<void> {',
    '        let idx = 0;',
    "        const sqliteSql = sql.replace(/:[0-9]+/g, () => { idx++; return '?'; });",
    '        db.prepare(sqliteSql).run(...params);',
    '      },',
    '    },',
    '  };',
    '}',
    '',
    `describe('${ctxLabel} Adapter (integration)', () => {`,
    '  let testDb: ReturnType<typeof createTestDb>;',
    '  let adapter: any;',
    '',
    '  // ADR-087: Per-test isolation — fresh database for each test',
    '  beforeEach(async () => {',
    '    testDb = createTestDb();',
    '    const telemetry = new ConsoleTelemetry();',
    `    // Dynamically import the real adapter`,
    `    const deps = await import('../server/dependencies.js');`,
    `    const factory = deps.createDependencies(testDb.client as any, { invoke: async () => ({}) } as any);`,
    `    adapter = factory.${camelCase(ctx.name)};`,
    '  });',
    '',
    '  afterEach(() => { testDb?.db?.close(); });',
    '',
    `  it('execute() inserts a real row into ${tableName}', async () => {`,
    `    const result = await adapter.execute('CreateTest', { name: 'integration-test' });`,
    '    expect(result.id).toBeDefined();',
    '    expect(typeof result.id).toBe(\'string\');',
    '    expect(result.id.length).toBeGreaterThan(0);',
    '',
    '    // Verify row exists in SQLite',
    `    const rows = testDb.db.prepare('SELECT * FROM ${tableName} WHERE id = ?').all(result.id);`,
    '    expect(rows).toHaveLength(1);',
    '  });',
    '',
    `  it('getById() retrieves inserted row', async () => {`,
    `    const created = await adapter.execute('CreateForGetById', { value: 42 });`,
    '    const found = await adapter.getById(created.id);',
    '    expect(found).not.toBeNull();',
    '    expect(found.id).toBe(created.id);',
    '  });',
    '',
    `  it('getById() returns null for non-existent id', async () => {`,
    `    const found = await adapter.getById('does-not-exist-99999');`,
    '    expect(found).toBeNull();',
    '  });',
    '',
    `  it('query() returns paginated results from real DB', async () => {`,
    '    // Insert 3 records',
    `    await adapter.execute('Insert1', { idx: 1 });`,
    `    await adapter.execute('Insert2', { idx: 2 });`,
    `    await adapter.execute('Insert3', { idx: 3 });`,
    '',
    '    const result = await adapter.query({}, 2, 0);',
    '    expect(result.rows.length).toBeLessThanOrEqual(2);',
    '    expect(result.total).toBeGreaterThanOrEqual(3);',
    '  });',
    '',
    `  it('query() with filters produces WHERE clause', async () => {`,
    `    await adapter.execute('StatusFilter', { region: 'EUROPE' });`,
    `    // Filter by status (the command name stored as status per ADR-048)`,
    `    const result = await adapter.query({ status: 'StatusFilter' }, 50, 0);`,
    '    expect(result.rows.length).toBeGreaterThanOrEqual(1);',
    `    expect(result.rows.every((r: any) => r.status === 'StatusFilter')).toBe(true);`,
    '  });',
    '',
    `  it('query() with invalid column name is ignored (SQL injection prevention)', async () => {`,
    `    // The regex /^[a-z_][a-z0-9_]*$/i should block this`,
    `    const result = await adapter.query({ 'DROP TABLE--': 'x', '1=1; --': 'y' }, 50, 0);`,
    '    // Should not throw, just ignore invalid keys',
    '    expect(result).toBeDefined();',
    '    expect(result.rows).toBeDefined();',
    '  });',
    '});',
    '',
  ].join('\n');
}

